DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='sislam_runtime') THEN CREATE ROLE sislam_runtime NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF; END $$;
CREATE TABLE municipalities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, state text NOT NULL DEFAULT 'BA', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK(email=lower(btrim(email))), name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, auth_version integer NOT NULL DEFAULT 1, encrypted_totp text, totp_counter bigint NOT NULL DEFAULT -1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('applicant','protocol','analyst','authority','inspector','ombudsman','municipal_admin','supplier')), active boolean NOT NULL DEFAULT true, UNIQUE(municipality_id,user_id));
CREATE INDEX memberships_user_idx ON memberships(user_id);
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), municipality_id uuid NOT NULL REFERENCES municipalities(id), auth_version integer NOT NULL, mfa_verified boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id); CREATE INDEX sessions_tenant_idx ON sessions(municipality_id); CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE rate_limits(key text PRIMARY KEY, hits integer NOT NULL DEFAULT 1, window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, registration text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', representative text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), UNIQUE(municipality_id,registration));
CREATE INDEX organizations_owner_idx ON organizations(owner_id); CREATE INDEX organizations_tenant_created_idx ON organizations(municipality_id,created_at DESC);
CREATE TABLE establishments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), organization_id uuid NOT NULL, name text NOT NULL, activity text NOT NULL, address text NOT NULL, latitude numeric(10,7), longitude numeric(10,7), capacity numeric NOT NULL CHECK(capacity>=0), area numeric NOT NULL CHECK(area>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), FOREIGN KEY(municipality_id,organization_id) REFERENCES organizations(municipality_id,id));
CREATE INDEX establishments_org_idx ON establishments(municipality_id,organization_id);
CREATE TABLE rule_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), activity text NOT NULL, version integer NOT NULL CHECK(version>0), title text NOT NULL, status text NOT NULL CHECK(status IN ('draft','approved_demo')), valid_from date NOT NULL, valid_until date, definition jsonb NOT NULL, source_reference text NOT NULL, approved_by uuid REFERENCES users(id), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), UNIQUE(municipality_id,activity,version), CHECK(valid_until IS NULL OR valid_until>=valid_from));
CREATE INDEX rules_activity_idx ON rule_versions(municipality_id,activity,status,valid_from); CREATE INDEX rules_creator_idx ON rule_versions(created_by); CREATE INDEX rules_approver_idx ON rule_versions(approved_by);
CREATE TABLE cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), establishment_id uuid NOT NULL, owner_id uuid NOT NULL REFERENCES users(id), assigned_to uuid REFERENCES users(id), protocol text, title text NOT NULL, request_type text NOT NULL DEFAULT 'initial' CHECK(request_type IN ('initial','renewal')), parent_id uuid, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','filed','screening','requirements','analysis','decision','closed')), rule_id uuid, rule_snapshot jsonb, classification jsonb, revision integer NOT NULL DEFAULT 1, filed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), UNIQUE(municipality_id,protocol), FOREIGN KEY(municipality_id,establishment_id) REFERENCES establishments(municipality_id,id), FOREIGN KEY(municipality_id,rule_id) REFERENCES rule_versions(municipality_id,id), FOREIGN KEY(municipality_id,parent_id) REFERENCES cases(municipality_id,id));
CREATE INDEX cases_owner_idx ON cases(owner_id); CREATE INDEX cases_assignee_idx ON cases(assigned_to); CREATE INDEX cases_establishment_idx ON cases(municipality_id,establishment_id); CREATE INDEX cases_rule_idx ON cases(municipality_id,rule_id); CREATE INDEX cases_parent_idx ON cases(municipality_id,parent_id); CREATE INDEX cases_queue_idx ON cases(municipality_id,status,updated_at DESC);
ALTER TABLE cases ADD COLUMN decision_outcome text CHECK(decision_outcome IN ('approved_demo','refused_demo')), ADD COLUMN decision_reason text, ADD COLUMN decided_by uuid REFERENCES users(id), ADD COLUMN decided_at timestamptz;
CREATE INDEX cases_decider_idx ON cases(decided_by);
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), case_id uuid NOT NULL, requirement_key text NOT NULL, version integer NOT NULL CHECK(version>0), filename text NOT NULL, media_type text NOT NULL, bytes integer NOT NULL CHECK(bytes>0 AND bytes<=10485760), sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'), storage_key text NOT NULL UNIQUE, scan_status text NOT NULL CHECK(scan_status IN ('clean','quarantine','demo_unscanned')), status text NOT NULL DEFAULT 'sent' CHECK(status IN ('sent','received','accepted','reservation','rejected')), uploaded_by uuid NOT NULL REFERENCES users(id), received_by uuid REFERENCES users(id), received_at timestamptz, reviewed_by uuid REFERENCES users(id), reviewed_at timestamptz, review_note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), UNIQUE(municipality_id,case_id,requirement_key,version), FOREIGN KEY(municipality_id,case_id) REFERENCES cases(municipality_id,id));
CREATE INDEX documents_case_idx ON documents(municipality_id,case_id); CREATE INDEX documents_uploader_idx ON documents(uploaded_by); CREATE INDEX documents_receiver_idx ON documents(received_by); CREATE INDEX documents_reviewer_idx ON documents(reviewed_by);
CREATE TABLE opinions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), case_id uuid NOT NULL, author_id uuid NOT NULL REFERENCES users(id), version integer NOT NULL, conclusion text NOT NULL CHECK(conclusion IN ('favorable','unfavorable','complement')), text text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','reviewed')), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), UNIQUE(municipality_id,case_id,version), FOREIGN KEY(municipality_id,case_id) REFERENCES cases(municipality_id,id));
CREATE INDEX opinions_case_idx ON opinions(municipality_id,case_id); CREATE INDEX opinions_author_idx ON opinions(author_id);
CREATE TABLE licenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), case_id uuid NOT NULL, opinion_id uuid NOT NULL, authority_id uuid NOT NULL REFERENCES users(id), number text NOT NULL, verification_code text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'approved_demo' CHECK(status IN ('approved_demo','published_demo','closed')), text text NOT NULL, valid_until date NOT NULL, approved_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, UNIQUE(municipality_id,id), UNIQUE(municipality_id,case_id), FOREIGN KEY(municipality_id,case_id) REFERENCES cases(municipality_id,id), FOREIGN KEY(municipality_id,opinion_id) REFERENCES opinions(municipality_id,id));
CREATE INDEX licenses_case_idx ON licenses(municipality_id,case_id); CREATE INDEX licenses_opinion_idx ON licenses(municipality_id,opinion_id); CREATE INDEX licenses_authority_idx ON licenses(authority_id); CREATE INDEX licenses_expiry_idx ON licenses(municipality_id,valid_until);
CREATE TABLE conditions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), license_id uuid NOT NULL, case_id uuid NOT NULL, title text NOT NULL, responsible text NOT NULL, due_date date NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','submitted','fulfilled','rejected')), evidence_document_id uuid, review_note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), FOREIGN KEY(municipality_id,license_id) REFERENCES licenses(municipality_id,id), FOREIGN KEY(municipality_id,case_id) REFERENCES cases(municipality_id,id), FOREIGN KEY(municipality_id,evidence_document_id) REFERENCES documents(municipality_id,id));
CREATE INDEX conditions_license_idx ON conditions(municipality_id,license_id); CREATE INDEX conditions_case_idx ON conditions(municipality_id,case_id); CREATE INDEX conditions_evidence_idx ON conditions(municipality_id,evidence_document_id); CREATE INDEX conditions_due_idx ON conditions(municipality_id,status,due_date);
CREATE TABLE notices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), case_id uuid NOT NULL, author_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, text text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','dispatched_demo','acknowledged_demo','answered')), days integer CHECK(days BETWEEN 1 AND 3650), counting text CHECK(counting IN ('calendar','business')), deadline_basis text, approved_by uuid REFERENCES users(id), dispatched_at timestamptz, acknowledged_at timestamptz, acknowledgement_evidence text, due_date date, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), FOREIGN KEY(municipality_id,case_id) REFERENCES cases(municipality_id,id), CHECK(due_date IS NULL OR acknowledged_at IS NOT NULL));
CREATE INDEX notices_case_idx ON notices(municipality_id,case_id); CREATE INDEX notices_author_idx ON notices(author_id); CREATE INDEX notices_approver_idx ON notices(approved_by);
CREATE TABLE complaints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), protocol text NOT NULL, title text NOT NULL, narrative text NOT NULL, location text NOT NULL, status text NOT NULL DEFAULT 'received' CHECK(status IN ('received','screening','diligence','investigation','concluded','archived')), case_id uuid, conclusion text, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), UNIQUE(municipality_id,protocol), FOREIGN KEY(municipality_id,case_id) REFERENCES cases(municipality_id,id));
CREATE INDEX complaints_case_idx ON complaints(municipality_id,case_id); CREATE INDEX complaints_creator_idx ON complaints(created_by); CREATE INDEX complaints_queue_idx ON complaints(municipality_id,status,created_at DESC);
CREATE TABLE complaint_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), complaint_id uuid NOT NULL, encrypted_contact text NOT NULL, UNIQUE(municipality_id,complaint_id), FOREIGN KEY(municipality_id,complaint_id) REFERENCES complaints(municipality_id,id));
CREATE TABLE inspections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), case_id uuid, complaint_id uuid, inspector_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, scheduled_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','completed','cancelled')), report text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), FOREIGN KEY(municipality_id,case_id) REFERENCES cases(municipality_id,id), FOREIGN KEY(municipality_id,complaint_id) REFERENCES complaints(municipality_id,id));
CREATE INDEX inspections_case_idx ON inspections(municipality_id,case_id); CREATE INDEX inspections_complaint_idx ON inspections(municipality_id,complaint_id); CREATE INDEX inspections_inspector_idx ON inspections(inspector_id); CREATE INDEX inspections_queue_idx ON inspections(municipality_id,scheduled_at);
CREATE TABLE support_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), user_id uuid NOT NULL REFERENCES users(id), granted_by uuid NOT NULL REFERENCES users(id), reason text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX support_grants_tenant_idx ON support_grants(municipality_id); CREATE INDEX support_grants_user_idx ON support_grants(user_id,expires_at); CREATE INDEX support_grants_grantor_idx ON support_grants(granted_by);
CREATE TABLE audit_heads(municipality_id uuid PRIMARY KEY REFERENCES municipalities(id), sequence bigint NOT NULL DEFAULT 0, last_hash text NOT NULL DEFAULT 'GENESIS');
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), actor_id uuid NOT NULL REFERENCES users(id), case_id uuid, sequence bigint NOT NULL, action text NOT NULL, payload jsonb NOT NULL, previous_hash text NOT NULL, event_hash text NOT NULL CHECK(event_hash ~ '^[a-f0-9]{64}$'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(municipality_id,id), UNIQUE(municipality_id,sequence), FOREIGN KEY(municipality_id,case_id) REFERENCES cases(municipality_id,id));
CREATE INDEX audit_tenant_idx ON audit_events(municipality_id,created_at,id); CREATE INDEX audit_actor_idx ON audit_events(actor_id); CREATE INDEX audit_case_idx ON audit_events(municipality_id,case_id);
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), event_key text NOT NULL UNIQUE, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox(municipality_id,status,created_at);
CREATE TABLE holidays(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), municipality_id uuid NOT NULL REFERENCES municipalities(id), date date NOT NULL, name text NOT NULL, UNIQUE(municipality_id,date));

-- Runtime role receives scoped access only. Missing tenant context denies every row.
GRANT USAGE ON SCHEMA public TO sislam_runtime;
GRANT SELECT ON municipalities TO sislam_runtime;
ALTER TABLE municipalities ENABLE ROW LEVEL SECURITY;
CREATE POLICY municipality_scope ON municipalities USING(id::text=current_setting('sislam.tenant',true));
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['memberships','organizations','establishments','rule_versions','cases','documents','opinions','licenses','conditions','notices','complaints','complaint_contacts','inspections','support_grants','audit_events','audit_heads','outbox','holidays'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO sislam_runtime',t);
  EXECUTE format('CREATE POLICY tenant_scope ON %I AS RESTRICTIVE FOR ALL TO sislam_runtime USING (municipality_id::text=current_setting(''sislam.tenant'',true)) WITH CHECK (municipality_id::text=current_setting(''sislam.tenant'',true))',t);
  EXECUTE format('CREATE POLICY tenant_access ON %I FOR ALL TO sislam_runtime USING (true) WITH CHECK (true)',t);
 END LOOP;
END $$;
CREATE POLICY applicant_organizations ON organizations AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true)<>'applicant' OR owner_id::text=current_setting('sislam.user',true)) WITH CHECK(current_setting('sislam.role',true)<>'applicant' OR owner_id::text=current_setting('sislam.user',true));
CREATE POLICY applicant_establishments ON establishments AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true)<>'applicant' OR EXISTS(SELECT 1 FROM organizations o WHERE o.id=organization_id AND o.owner_id::text=current_setting('sislam.user',true)));
CREATE POLICY applicant_cases ON cases AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true)<>'applicant' OR owner_id::text=current_setting('sislam.user',true));
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['documents','opinions','licenses','conditions','notices','inspections'] LOOP
  EXECUTE format('CREATE POLICY applicant_case_scope ON %I AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting(''sislam.role'',true)<>''applicant'' OR EXISTS(SELECT 1 FROM cases c WHERE c.id=case_id AND c.owner_id::text=current_setting(''sislam.user'',true)))',t);
 END LOOP;
END $$;
CREATE POLICY applicant_audit_scope ON audit_events AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true)<>'applicant' OR actor_id::text=current_setting('sislam.user',true) OR EXISTS(SELECT 1 FROM cases c WHERE c.id=case_id AND c.owner_id::text=current_setting('sislam.user',true))) WITH CHECK(actor_id::text=current_setting('sislam.user',true));
CREATE POLICY confidential_complaints ON complaints AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true) IN ('ombudsman','inspector','authority'));
CREATE POLICY confidential_contacts ON complaint_contacts AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true) IN ('ombudsman','authority'));
CREATE POLICY case_role_scope ON cases AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true) IN ('applicant','protocol','analyst','authority','inspector','municipal_admin','supplier'));
CREATE POLICY organization_role_scope ON organizations AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true)<>'ombudsman');
CREATE POLICY establishment_role_scope ON establishments AS RESTRICTIVE FOR ALL TO sislam_runtime USING(current_setting('sislam.role',true)<>'ombudsman');
REVOKE UPDATE ON audit_events FROM sislam_runtime;
REVOKE UPDATE ON rule_versions FROM sislam_runtime;
REVOKE INSERT,UPDATE ON memberships,support_grants FROM sislam_runtime;
REVOKE ALL ON users,sessions,rate_limits FROM PUBLIC,sislam_runtime;
CREATE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Registro imutável: crie uma nova versão'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER rule_immutable BEFORE UPDATE OR DELETE ON rule_versions FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE FUNCTION preserve_document_original() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF ROW(NEW.municipality_id,NEW.case_id,NEW.requirement_key,NEW.version,NEW.filename,NEW.media_type,NEW.bytes,NEW.sha256,NEW.storage_key,NEW.uploaded_by,NEW.created_at) IS DISTINCT FROM ROW(OLD.municipality_id,OLD.case_id,OLD.requirement_key,OLD.version,OLD.filename,OLD.media_type,OLD.bytes,OLD.sha256,OLD.storage_key,OLD.uploaded_by,OLD.created_at) THEN RAISE EXCEPTION 'O original do documento é imutável'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER document_original_immutable BEFORE UPDATE ON documents FOR EACH ROW EXECUTE FUNCTION preserve_document_original();
CREATE FUNCTION preserve_protocol_rule() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.filed_at IS NOT NULL AND ROW(NEW.protocol,NEW.rule_id,NEW.rule_snapshot,NEW.filed_at,NEW.municipality_id,NEW.establishment_id,NEW.owner_id) IS DISTINCT FROM ROW(OLD.protocol,OLD.rule_id,OLD.rule_snapshot,OLD.filed_at,OLD.municipality_id,OLD.establishment_id,OLD.owner_id) THEN RAISE EXCEPTION 'O protocolo e a regra original são imutáveis'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER case_protocol_immutable BEFORE UPDATE ON cases FOR EACH ROW EXECUTE FUNCTION preserve_protocol_rule();
